  assert.match(gitignore, /^\*\.md$/m);
  assert.match(gitignore, /^!\/README\.md$/m);
  assert.match(gitignore, /^!\/\.github\/pull_request_template\.md$/m);
  assert.match(gitignore, /^!\/\.github\/PULL_REQUEST_TEMPLATE\/\*\.md$/m);
  assert.match(gitignore, /^AGENTS\.md$/m);
