test("모바일 홈 shell과 주요 상태 UI 회귀 테스트는 유지된다", () => {
  const home = read(
    "apps/mobile/lib/features/home/presentation/home_screen.dart",
  );
  const widgetTest = read("apps/mobile/test/widget_test.dart");

  assert.match(home, /int _selectedTabIndex = 0/);
  assert.match(home, /if \(_selectedTabIndex == 0\)[\s\S]*NetworkMapScreen\(/);
  assert.doesNotMatch(home, /homeBottomNavigationBar/);
  assert.match(widgetTest, /기본 앱은 저장소가 없어도 노선도 중심 첫 화면을 보여준다/);
  assert.match(widgetTest, /노선도 첫 화면은 하단 광고 위에 지도 조작을 유지한다/);
  // #1933: 폼 페이지 제거로 대체된 현행 전환 테스트 앵커
  assert.match(widgetTest, /노선도에서 출발·도착을 정하면 길찾기 결과 화면으로 전환한다/);
  assert.match(widgetTest, /find\.byKey\(const Key\('homeBottomNavigationBar'\)\), findsNothing/);
  assert.match(widgetTest, /find\.byKey\(const Key\('bottomNavHome'\)\), findsNothing/);
  assert.match(widgetTest, /find\.byKey\(const Key\('bottomNavSaved'\)\), findsNothing/);
  assert.match(widgetTest, /홈은 시설 알림과 최근 경로 로드 실패를 인라인 오류 없이 넘긴다/);
  assert.match(widgetTest, /노선도 로드 실패는 재시도만 보여준다/);
  assert.doesNotMatch(home, /class _HomeHero/);
  assert.doesNotMatch(home, /class _HomeAdaptiveContent/);
  assert.match(home, /return const SizedBox\.shrink\(\);/);
});

test("모바일 역 검색 결과 시스템 글자 크기 문구 회귀 테스트는 유지된다", () => {
  const stationSearchBody = read(
    "apps/mobile/lib/features/stations/presentation/station_search_body.dart",
  );
  const widgetTest = read("apps/mobile/test/widget_test.dart");
  const resultTileMatch = stationSearchBody.match(
    /class _StationSearchResultTile[\s\S]*?class _StationRoleActionBar/,
  );
  const largeTextTestMatch = widgetTest.match(
    /testWidgets\('역 검색 결과 핵심 문구는 시스템 글자 크기에서 한 줄 말줄임으로 고정하지 않는다'[\s\S]*?\n  testWidgets\('/,
  );

  assert.ok(resultTileMatch, "_StationSearchResultTile block not found");
  const resultTile = resultTileMatch[0];
  // #1933: 결과 행은 노선마다 한 행씩(_StationSearchResultLineRow) 펼치고
  // 각 행 우측에 해당 노선 배지(StationLineBadge) 하나만 둔다. '+N' 요약·거리 문구 없음.
  assert.match(resultTile, /_StationSearchResultLineRow\(/);
  assert.match(resultTile, /StationLineBadge\(line: line/);
  assert.doesNotMatch(resultTile, /maxBadgeCount/);
  // 역명만 노출한다(거리·노선 요약 부가 문구 제거).
  assert.match(resultTile, /child: Text\(\s*stationName/);
  assert.doesNotMatch(resultTile, /result\.distanceLabel/);
  assert.doesNotMatch(resultTile, /maxLines:\s*1/);
  assert.doesNotMatch(resultTile, /overflow:\s*TextOverflow\.ellipsis/);
  assert.ok(largeTextTestMatch, "station search large text widget test block not found");
  const largeTextTest = largeTextTestMatch[0];
  assert.match(largeTextTest, /TextScaler\.linear\(2\.0\)/);
  assert.match(largeTextTest, /김포공항국제선환승센터/);
  assert.match(largeTextTest, /수도권 9호선 급행/);
  assert.match(largeTextTest, /공항철도 직통 일반 공용/);
  // #1933: 환승역은 노선마다 한 행씩 펼치므로 역명 Text가 노선 수만큼 있다.
  assert.match(largeTextTest, /expect\(nameWidgets, findsNWidgets\(2\)\)/);
  assert.match(largeTextTest, /expect\(nameWidget\.maxLines, isNot\(1\)\)/);
  assert.match(largeTextTest, /expect\(nameWidget\.overflow, isNot\(TextOverflow\.ellipsis\)\)/);
});

