test("production row provenance는 snapshot/provider/evidence hash gate를 유지한다", () => {
  const input = readJson("tools/datapack/inputs/capital-pilot-production-source-input.json");
  const schema = read("tools/datapack/schema/catalog-schema.sql");
  const builder = read("tools/datapack/build-datapack.mjs");
  const validator = read("tools/datapack/validate-datapack.mjs");
  const mobileTables = read("apps/mobile/lib/core/database/catalog/catalog_tables.dart");
  const mobileDatabase = read("apps/mobile/lib/core/database/catalog/catalog_database.dart");
  const schedulePostgresMigration = read("backend/src/main/resources/db/migration/postgresql/V29__canonical_transit_schedule.sql");
  const scheduleH2Migration = read("backend/src/main/resources/db/migration/h2/V29__canonical_transit_schedule.sql");
  const pathwayPostgresMigration = read("backend/src/main/resources/db/migration/postgresql/V30__canonical_station_pathways.sql");
  const pathwayH2Migration = read("backend/src/main/resources/db/migration/h2/V30__canonical_station_pathways.sql");

  for (const row of input.facilityRows) {
    assert.match(row.sourceSnapshotId, /^[a-z0-9-]+-snapshot-\d{8}$/);
    assert.match(row.providerRecordHash, /^[0-9a-f]{64}$/);
    assert.match(row.evidenceHash, /^[0-9a-f]{64}$/);
    assert.doesNotMatch(row.providerRecordHash, /^([0-9a-f])\1{63}$/);
    assert.doesNotMatch(row.evidenceHash, /^([0-9a-f])\1{63}$/);
  }
  for (const row of input.routeEdges) {
    assert.match(row.sourceSnapshotId, /^[a-z0-9-]+-snapshot-\d{8}$/);
    assert.match(row.providerRecordHash, /^[0-9a-f]{64}$/);
    assert.match(row.evidenceHash, /^[0-9a-f]{64}$/);
    assert.doesNotMatch(row.providerRecordHash, /^([0-9a-f])\1{63}$/);
    assert.doesNotMatch(row.evidenceHash, /^([0-9a-f])\1{63}$/);
  }
  for (const row of input.movementPathCandidates) {
    assert.match(row.sourceSnapshotId, /^[a-z0-9-]+-snapshot-\d{8}$/);
    assert.match(row.providerRecordHash, /^[0-9a-f]{64}$/);
    assert.match(row.evidenceHash, /^[0-9a-f]{64}$/);
    assert.doesNotMatch(row.providerRecordHash, /^([0-9a-f])\1{63}$/);
    assert.doesNotMatch(row.evidenceHash, /^([0-9a-f])\1{63}$/);
  }

  assert.match(schema, /CREATE TABLE network_edges \([\s\S]+source_snapshot_id TEXT NOT NULL DEFAULT ''[\s\S]+provider_record_hash TEXT NOT NULL DEFAULT ''/);
  assert.match(schema, /CREATE TABLE facilities \([\s\S]+source_snapshot_id TEXT NOT NULL DEFAULT ''[\s\S]+provider_record_hash TEXT NOT NULL DEFAULT ''/);
  assert.match(schema, /CREATE TABLE facility_status_snapshots \([\s\S]+facility_id TEXT NOT NULL[\s\S]+expires_at INTEGER/);
  assert.match(schema, /CREATE TABLE station_facility_evidence \([\s\S]+provider_record_hash TEXT NOT NULL[\s\S]+strict_route_eligible INTEGER NOT NULL DEFAULT 0/);
  assert.match(schema, /CREATE TABLE transit_stop_times \([\s\S]+arrival_seconds INTEGER NOT NULL[\s\S]+departure_seconds INTEGER NOT NULL/);
  assert.match(schema, /CREATE TABLE fare_zones \(/);
  assert.match(schema, /CREATE TABLE fare_rules \([\s\S]+additional_steps_json TEXT NOT NULL DEFAULT '\[\]'/);
  assert.match(schema, /CREATE TABLE station_fare_zones \([\s\S]+FOREIGN KEY \(station_id, line_id\) REFERENCES station_lines/);

  // #1911: 수도권 통합요금 50km 초과 구간은 8km당 100원(기존 5km당 100원 과대 산정 수정).
  // fixture와 Dart 소스(공용 상수)의 additionalSteps 값이 어긋나지 않도록 고정한다.
  const fixture = readJson("tools/datapack/fixtures/catalog-fixture.json");
  const fixtureAdditionalSteps = fixture.packs[0].fareRules[0].additionalSteps;
  const additionalStepsConstantMatch = mobileDatabase.match(
    /const capitalIntegratedAdditionalStepsJson =\s*((?:'[^']*'\s*)+);/,
  );
  assert.ok(
    additionalStepsConstantMatch,
    "catalog_database.dart에서 capitalIntegratedAdditionalStepsJson 상수를 찾을 수 없다",
  );
  const additionalStepsJsonLiteral = additionalStepsConstantMatch[1]
    .trim()
    .split("\n")
    .map((line) => line.trim().replace(/^'|'$/g, ""))
    .join("");
  const dartAdditionalSteps = JSON.parse(additionalStepsJsonLiteral);

  assert.deepEqual(dartAdditionalSteps, fixtureAdditionalSteps);
  assert.equal(dartAdditionalSteps.length, 9);
  for (const step of dartAdditionalSteps.slice(0, 8)) {
    assert.deepEqual(step, { distanceMeters: 5000, cardFare: 100, cashFare: 100 });
  }
  assert.deepEqual(dartAdditionalSteps[8], {
    distanceMeters: 8000,
    cardFare: 100,
    cashFare: 100,
  });
  assert.match(schema, /CREATE TABLE station_pathway_edges \([\s\S]+requires_facility_id TEXT[\s\S]+legacy_internal_route_edge_id TEXT NOT NULL DEFAULT ''/);
  assert.match(schema, /CREATE TABLE internal_route_edges \([\s\S]+source_snapshot_id TEXT NOT NULL DEFAULT ''[\s\S]+provider_record_hash TEXT NOT NULL DEFAULT ''/);
  assert.match(builder, /"station_facility_evidence"/);
  assert.match(builder, /"transit_stop_times"/);
  assert.match(builder, /"fare_zones"/);
  assert.match(builder, /"station_fare_zones"/);
  assert.match(builder, /"source_snapshot_id"/);
  assert.match(builder, /"provider_record_hash"/);
  assert.match(validator, /validateProductionStationFacilityEvidence/);
  assert.match(validator, /validateTransitSchedule/);
  assert.match(validator, /validateFareTables/);
  assert.match(validator, /validateStationPathways/);
  assert.match(validator, /"source_snapshot_id"/);
  assert.match(validator, /"provider_record_hash"/);
  assert.match(mobileTables, /class TransitStopTimes extends Table/);
  assert.match(mobileTables, /class StationPathwayEdges extends Table/);
  assert.match(mobileTables, /class TransferRules extends Table/);
  assert.match(mobileTables, /class FareZones extends Table/);
  assert.match(mobileTables, /class StationFareZones extends Table/);
  assert.match(mobileTables, /class FacilityStatusSnapshots extends Table/);
  assert.match(mobileDatabase, /const catalogDatabaseSchemaVersion = 18/);
  assert.match(mobileDatabase, /int get schemaVersion => catalogDatabaseSchemaVersion/);
  assert.match(mobileDatabase, /_createTransitScheduleIndexes/);
  assert.match(mobileDatabase, /_createStationPathwayIndexes/);
  assert.match(mobileDatabase, /_createFacilityStatusSnapshotIndexes/);
  assert.match(mobileDatabase, /_createRouteMapLineTracksTable/);
  assert.match(schedulePostgresMigration, /CREATE TABLE IF NOT EXISTS transit_stop_times/);
  assert.match(scheduleH2Migration, /CREATE TABLE IF NOT EXISTS transit_stop_times/);
  assert.match(pathwayPostgresMigration, /CREATE TABLE IF NOT EXISTS station_pathway_edges/);
  assert.match(pathwayH2Migration, /CREATE TABLE IF NOT EXISTS station_pathway_edges/);
  assert.match(validator, /validateProductionInternalRouteEdgeProvenance/);
  assert.match(validator, /validateNetworkEdgeBaseProvenance/);
  assert.match(validator, /is placeholder evidence/);
  assert.match(mobileTables, /class StationFacilityEvidence extends Table/);
  assert.match(mobileTables, /sourceSnapshotId[\s\S]+source_snapshot_id/);
  assert.match(mobileTables, /providerRecordHash[\s\S]+provider_record_hash/);
  assert.match(mobileDatabase, /const catalogDatabaseSchemaVersion = 18/);
  assert.match(mobileDatabase, /int get schemaVersion => catalogDatabaseSchemaVersion/);
  assert.match(mobileDatabase, /StationFacilityEvidence/);
  assert.match(mobileDatabase, /FacilityStatusSnapshots/);
  assert.match(mobileDatabase, /_addSourceEvidenceProvenanceColumns/);
});

test("strict route coverage는 UNKNOWN edge와 unpromoted movement candidate를 제외한다", async () => {
  const validator = read("tools/datapack/validate-datapack.mjs");
  const importer = read("tools/datapack/import-official-sources.mjs");
  const input = readJson("tools/datapack/inputs/capital-pilot-production-source-input.json");
  const outputDir = await mkdtemp(path.join(tmpdir(), "easysubway-strict-route-coverage-"));
  const importedFixturePath = path.join(outputDir, "capital-pilot-production.json");

  // #1996: 게시 coverage는 검증된 상태 3분류(AVAILABLE/UNDER_MAINTENANCE/NO_OFFICIAL_FEED)를 verified로 인정하고
  // 증거 없는 UNKNOWN만 차단한다. strict route 보장(#1394)은 AVAILABLE 전용으로 불변.
  assert.match(validator, /const verifiedAccessibilityStatuses = new Set\(\["AVAILABLE", "UNDER_MAINTENANCE", "NO_OFFICIAL_FEED"\]\)/);
  assert.match(validator, /function isAccessibilityProvenanceCandidate/);
  assert.match(validator, /function isUnverifiedAccessibilityCoverageEdge/);
  assert.match(validator, /!verifiedAccessibilityStatuses\.has\(String\(edge\.accessibility_status/);
  assert.match(validator, /unverifiedAccessibilityCoverageEdges/);
  // strict guarantee 불변: transfer strict edge·movement pathway·strict facility 는 AVAILABLE 전용.
  assert.match(validator, /strictAccessibilityStatus !== "AVAILABLE"/);
  assert.match(validator, /String\(edge\.accessibility_status \?\? ""\)\.toUpperCase\(\) !== "AVAILABLE"/);

  for (const candidate of input.movementPathCandidates) {
    assert.match(candidate.evidenceHash, /^[0-9a-f]{64}$/);
  }
  assert.match(importer, /reviewStatus: "PENDING_ADMIN_REVIEW"/);
  assert.doesNotMatch(importer, /APPROVED_FOR_GRAPH/);

  await execFileAsync(
    process.execPath,
    [
      "tools/datapack/import-official-sources.mjs",
      "--inventory",
      "tools/datapack/source-inventory.json",
      "--input",
      "tools/datapack/inputs/capital-pilot-production-source-input.json",
      "--output",
      importedFixturePath,
    ],
    { cwd: root },
  );
  const importedPack = JSON.parse(readFileSync(importedFixturePath, "utf8")).packs[0];
  assert.deepEqual(
    importedPack.movementPathCandidates.map((candidate) => ({
      id: candidate.id,
      reviewStatus: candidate.reviewStatus,
    })),
    input.movementPathCandidates.map((candidate) => ({
      id: candidate.id,
      reviewStatus: "PENDING_ADMIN_REVIEW",
    })),
  );
  assert.equal(importedPack.networkEdges.some((edge) => edge.edgeType === "MOVEMENT"), false);
  // 필수 시설유형 커버리지 증거는 denominator(2역 x 3유형=6)와 정확히 일치한다.
  const requiredFacilityEvidence = importedPack.stationFacilityEvidence.filter(
    (row) => row.facilityType !== "ACCESSIBILITY_STATUS_PROBE",
  );
  assert.equal(requiredFacilityEvidence.length, input.supportedV1Scope.facilityCoverageDenominator.expectedRows);
  // #1996: 접근성 상태 실측 증거(ACCESSIBILITY_STATUS_PROBE)는 별도 행으로 추가된다.
  // 사당 UNDER_MAINTENANCE(EXISTS·보수중·strict 부적격), 상록수 NO_OFFICIAL_FEED(NOT_EXISTS·부재 기록).
  const probeEvidence = importedPack.stationFacilityEvidence.filter(
    (row) => row.facilityType === "ACCESSIBILITY_STATUS_PROBE",
  );
  assert.deepEqual(
    probeEvidence
      .map((row) => ({
        stationId: row.stationId,
        evidenceKind: row.evidenceKind,
        operationalStatus: row.operationalStatus,
        strictRouteEligible: row.strictRouteEligible,
      }))
      .sort((left, right) => left.stationId.localeCompare(right.stationId)),
    [
      { stationId: "station-sadang", evidenceKind: "EXISTS", operationalStatus: "UNDER_MAINTENANCE", strictRouteEligible: false },
      { stationId: "station-sangnoksu", evidenceKind: "NOT_EXISTS", operationalStatus: "NOT_COVERED", strictRouteEligible: false },
    ],
  );
});

