test("운영 백업 복구 리허설 gate는 필수 백업 대상과 dry-run 검증 명령을 고정한다", () => {
  const gatePath = "apps/mobile/release/backup-restore-rehearsal-gate.json";
  const checkScriptPath = "tools/ops/backup-restore-rehearsal-check.mjs";
  const photoRestoreCheckPath = "tools/ops/facility-report-photo-restore-check.mjs";
  assert.ok(existsSync(path.join(root, gatePath)), "backup restore rehearsal gate artifact must exist");
  assert.ok(existsSync(path.join(root, checkScriptPath)), "backup restore rehearsal check script must exist");
  assert.ok(existsSync(path.join(root, photoRestoreCheckPath)), "photo restore rehearsal check script must exist");

  const gate = readJson(gatePath);
  const checkScript = read(checkScriptPath);
  const photoRestoreCheckScript = read(photoRestoreCheckPath);

  assert.equal(gate.schemaVersion, 1);
  assert.equal(gate.applicationId, "easysubway");
  assert.equal(gate.releaseGate, "backup-restore-rehearsal");
  assert.equal(gate.releaseBlockerPolicy, true);
  assert.doesNotMatch(JSON.stringify(gate), /\b(TBD|TODO|PLACEHOLDER)\b|\.{3}/i);

  const backupTargets = new Map(gate.backupTargets.map((target) => [target.id, target]));
  const requiredBackupTargetIds = [
    "postgres_application_database",
    "facility_report_photo_objects",
    "datapack_source_inventory",
    "datapack_release_manifest_history",
  ];
  assert.deepEqual([...backupTargets.keys()].sort(), requiredBackupTargetIds.toSorted());

  for (const id of requiredBackupTargetIds) {
    const target = backupTargets.get(id);
    assert.match(target.ownerKo, /담당자/);
    assert.ok(target.backupCommand.length > 0, `${id} must define backup command`);
    assert.ok(target.restoreRehearsalCommand.length > 0, `${id} must define restore rehearsal command`);
    assert.ok(target.successEvidence.length > 0, `${id} must define success evidence`);
    assert.ok(target.failureConditions.length > 0, `${id} must define failure conditions`);
    for (const artifact of target.linkedArtifacts) {
      assert.ok(existsSync(path.join(root, artifact)), `${id} linked artifact must exist: ${artifact}`);
    }
  }

  const photoTarget = backupTargets.get("facility_report_photo_objects");
  const postgresTarget = backupTargets.get("postgres_application_database");
  assert.equal(
    postgresTarget.backupCommand,
    "tools/ops/postgres-backup.sh <deploy-root>/backups/postgres",
  );
  assert.equal(
    photoTarget.backupCommand,
    "tools/ops/facility-report-photo-backup.sh",
  );
  assert.equal(postgresTarget.retentionDays, 30);
  assert.match(postgresTarget.retentionCommand, /prune-sensitive-backups\.mjs/);
  assert.ok(postgresTarget.linkedArtifacts.includes(".github/workflows/sensitive-backup-retention.yml"));
  assert.equal(photoTarget.scope, "local-rehearsal-only");
  assert.equal(photoTarget.retentionDays, undefined);
  assert.equal(photoTarget.retentionCommand, undefined);
  assert.ok(!photoTarget.linkedArtifacts.includes(".github/workflows/sensitive-backup-retention.yml"));
  assert.equal(
    photoTarget.restoreRehearsalCommand,
    'node tools/ops/facility-report-photo-restore-check.mjs "$EASYSUBWAY_PHOTO_RESTORE_DIR"',
  );
  assert.ok(
    photoTarget.linkedArtifacts.includes(photoRestoreCheckPath),
    "facility photo restore target must link the restore check script",
  );
  const sourceArchiveTarget = backupTargets.get("datapack_source_inventory");
  assert.equal(
    sourceArchiveTarget.restoreRehearsalCommand,
    'EASYSUBWAY_DATA_SOURCE_RESTORE_DIR="$RESTORED_ARCHIVE_DIR" node tools/ops/data-source-raw-archive-restore-check.mjs && node tools/datapack/validate-source-inventory.mjs --inventory tools/datapack/source-inventory.json',
  );
  assert.ok(sourceArchiveTarget.linkedArtifacts.includes("tools/ops/data-source-raw-archive-materialize.mjs"));
  assert.ok(sourceArchiveTarget.linkedArtifacts.includes("tools/ops/data-source-raw-archive-restore-check.mjs"));
  assert.ok(sourceArchiveTarget.linkedArtifacts.includes("tools/ops/data-source-raw-archive-csv.mjs"));
  assert.match(sourceArchiveTarget.successEvidence, /payload hash·size·ID 검증/);

  assert.match(gate.rehearsalPolicy.frequencyKo, /월 1회|릴리즈/);
  assert.match(gate.rehearsalPolicy.dataSafetyKo, /운영 데이터 직접 복원 금지|격리/);
  assert.match(gate.rehearsalPolicy.requiredOutputKo, /backup-restore-rehearsal/);
  assert.match(gate.rehearsalPolicy.sensitiveBackupRetentionKo, /일일 workflow/);
  assert.match(gate.rehearsalPolicy.sensitiveBackupRetentionKo, /30일/);
  assert.match(checkScript, /backup-restore-rehearsal-gate\.json/);
  assert.match(checkScript, /postgres_application_database/);
  assert.match(checkScript, /datapack_release_manifest_history/);
  assert.match(photoRestoreCheckScript, /manifest\.tsv/);
  assert.match(photoRestoreCheckScript, /sha256/);

  execFileSync(process.execPath, [checkScriptPath], { cwd: root, encoding: "utf8" });
});

test("저장소 지속적 통합은 Docker Compose 설정을 검증한다", () => {
  const workflow = read(".github/workflows/ci.yml");

  assert.match(workflow, /Repository CI \/ Validate Docker Compose config/);
  assert.match(workflow, /docker compose --env-file \.env\.example -f infra\/docker-compose\.yml config --quiet/);
});

test("로컬 관측성 스택은 Prometheus와 Grafana 기준선을 제공한다", () => {
  const build = read("backend/build.gradle");
  const applicationYml = read("backend/src/main/resources/application.yml");
  const applicationDevYml = read("backend/src/main/resources/application-dev.yml");
  const compose = read("infra/docker-compose.yml");
  const prometheusConfig = read("infra/prometheus/prometheus.yml");
  const prometheusAlerts = read("infra/prometheus/alerts.yml");
  const alertmanagerConfig = read("infra/alertmanager/alertmanager.local.yml");
  const alertmanagerTemplate = read("infra/alertmanager/templates/email.tmpl");
  const grafanaDatasource = read("infra/grafana/provisioning/datasources/prometheus.yml");

  assert.match(build, /implementation 'io\.micrometer:micrometer-registry-prometheus'/);
  // #2376: actuator Prometheus 메트릭을 docker network 내부에서 직접 scrape하기 위해 prometheus를 노출한다
  // (공개 경로 차단은 nginx host 템플릿에서 보장 — backend-deploy.test.mjs 참조).
  assert.match(applicationYml, /management:\s*\n\s*endpoints:\s*\n\s*web:\s*\n\s*exposure:\s*\n\s*include:\s*["']?health\s*,\s*info\s*,\s*prometheus["']?/);
  assert.match(applicationDevYml, /management:\s*\n\s*endpoints:\s*\n\s*web:\s*\n\s*exposure:\s*\n\s*include:\s*["']?health\s*,\s*info\s*,\s*prometheus["']?/);

  assert.match(compose, /prometheus:\n/);
  assert.match(compose, /prometheus:[\s\S]*profiles:\s*\n\s*-\s*observability/);
  assert.match(compose, /image: prom\/prometheus:v[0-9]+\.[0-9]+\.[0-9]+/);
  assert.match(compose, /--web\.external-url=\$\{EASYSUBWAY_PROMETHEUS_EXTERNAL_URL:-http:\/\/localhost:9090\}/);
  assert.match(compose, /\.\/prometheus\/prometheus\.yml:\/etc\/prometheus\/prometheus\.yml:ro/);
  assert.match(compose, /\.\/prometheus\/alerts\.yml:\/etc\/prometheus\/alerts\.yml:ro/);
  assert.match(compose, /"\$\{EASYSUBWAY_PROMETHEUS_BIND:-127\.0\.0\.1\}:\$\{EASYSUBWAY_PROMETHEUS_PORT:-9090\}:9090"/);
  assert.match(compose, /prometheus-data:\/prometheus/);
  assert.match(compose, /wget --spider -q http:\/\/localhost:9090\/-\/healthy/);

  assert.match(compose, /alertmanager:\n/);
  assert.match(compose, /alertmanager:[\s\S]*profiles:\s*\n\s*-\s*observability/);
  assert.match(compose, /image: prom\/alertmanager:v0\.33\.0/);
  assert.match(compose, /--web\.external-url=\$\{EASYSUBWAY_ALERTMANAGER_EXTERNAL_URL:-http:\/\/localhost:9093\}/);
  assert.match(compose, /\$\{EASYSUBWAY_ALERTMANAGER_CONFIG_FILE:-\.\/alertmanager\/alertmanager\.local\.yml\}:\/etc\/alertmanager\/alertmanager\.yml:ro/);
  assert.match(compose, /\.\/alertmanager\/templates:\/etc\/alertmanager\/templates:ro/);
  assert.match(compose, /alertmanager-data:\/alertmanager/);

  assert.match(compose, /grafana:\n/);
  assert.match(compose, /grafana:[\s\S]*profiles:\s*\n\s*-\s*observability/);
  assert.match(compose, /image: grafana\/grafana:[0-9]+\.[0-9]+\.[0-9]+/);
  assert.match(compose, /"\$\{EASYSUBWAY_GRAFANA_BIND:-127\.0\.0\.1\}:\$\{EASYSUBWAY_GRAFANA_PORT:-3000\}:3000"/);
  assert.match(compose, /GF_SECURITY_ADMIN_PASSWORD: \$\{EASYSUBWAY_GRAFANA_ADMIN_PASSWORD:-easysubway_local\}/);
  assert.match(compose, /grafana-data:\/var\/lib\/grafana/);
  assert.match(compose, /\.\/grafana\/provisioning:\/etc\/grafana\/provisioning:ro/);
  assert.match(compose, /depends_on:\s*\n\s*prometheus:\s*\n\s*condition: service_healthy[\s\S]*loki:\s*\n\s*condition: service_healthy/);

  assert.match(prometheusConfig, /job_name: "easysubway-backend"/);
  assert.match(prometheusConfig, /http:\/\/backend:8080\/actuator\/health\/readiness/);
  assert.match(prometheusConfig, /job_name: "back_worker"/);
  assert.match(prometheusConfig, /http:\/\/back-worker:8080\/actuator\/health\/readiness/);
  assert.match(prometheusConfig, /job_name: "docker_runtime_probe"/);
  assert.match(prometheusConfig, /targets: \["docker-runtime-probe:8080"\]/);
  assert.match(prometheusConfig, /job_name: "public_edge_probe"/);
  assert.match(compose, /public-edge-probe:\n(?: {4}[^\n]*\n)* {4}restart: unless-stopped/);
  assert.match(compose, /docker-runtime-probe:\n(?: {4}[^\n]*\n)* {4}restart: unless-stopped/);
  assert.match(prometheusConfig, /metrics_path: "\/probe"/);
  assert.match(prometheusConfig, /module: \[http_2xx\]/);
  assert.match(prometheusConfig, /https:\/\/easysubway-api\.aquilaxk\.site\/actuator\/health\/readiness/);
  assert.match(prometheusConfig, /replacement: public-edge-probe:9115/);
  // #2376: backend actuator 메트릭 직접 scrape job. docker network 내부 backend:8080/actuator/prometheus.
  assert.match(prometheusConfig, /job_name: "backend_app_metrics"/);
  assert.match(prometheusConfig, /job_name: "backend_app_metrics"\s*\n\s*metrics_path: "\/actuator\/prometheus"\s*\n\s*static_configs:\s*\n\s*-\s*targets:\s*\n\s*-\s*"backend:8080"/);
  // 임시 blue/green standby는 상시 대상이 아니라 scrape 대상에서 제외한다(down 노이즈 방지).
  assert.doesNotMatch(prometheusConfig, /backend-standby:8080/);
  assert.doesNotMatch(prometheusConfig, /host\.docker\.internal:8080/);
  assert.match(prometheusConfig, /alertmanagers:\s*\n\s*-\s*static_configs:\s*\n\s*-\s*targets: \["alertmanager:9093"\]/);
  assert.match(prometheusConfig, /rule_files:\s*\n\s*-\s*\/etc\/prometheus\/alerts\.yml/);

  assert.match(prometheusAlerts, /alert: AquilaPublicEdgeProbeScrapeDown/);
  assert.match(prometheusAlerts, /alert: AquilaDockerRuntimeProbeScrapeDown/);
  assert.match(prometheusAlerts, /alert: AquilaBackWorkerScrapeDown/);
  assert.match(prometheusAlerts, /alert: AquilaPublicEdgeProbeScrapeDown[\s\S]*severity: warning[\s\S]*title_ko: "공개 접속 점검 실패"[\s\S]*impact_ko: "외부에서 API readiness를 확인하는 관측 신호가 멈췄습니다\."[\s\S]*action_ko: "public-edge-probe 컨테이너 상태와 외부 HTTPS readiness 응답을 확인하세요\."/);
  assert.match(prometheusAlerts, /alert: AquilaDockerRuntimeProbeScrapeDown[\s\S]*severity: warning[\s\S]*title_ko: "Docker 런타임 점검 실패"[\s\S]*impact_ko: "컨테이너 상태 관측 신호가 멈춰 Docker 기반 장애 탐지가 늦어질 수 있습니다\."[\s\S]*action_ko: "docker-runtime-probe 컨테이너 상태와 Docker socket 접근 권한을 확인하세요\."/);
  assert.match(prometheusAlerts, /alert: AquilaBackWorkerScrapeDown[\s\S]*severity: critical[\s\S]*title_ko: "백그라운드 작업자 상태 점검 실패"[\s\S]*impact_ko: "작업 큐와 DLQ 관련 알림 평가가 늦거나 멈출 수 있습니다\."[\s\S]*action_ko: "back-worker 컨테이너 상태와 \/actuator\/health\/readiness 응답을 확인하세요\."/);
  // #2376 dead-man's switch: backend_app_metrics scrape가 멈추면 freshness 경보가 조용히 멈추므로 그 무음을 감시한다.
  assert.match(prometheusAlerts, /alert: AquilaBackendAppMetricsScrapeDown/);
  assert.match(prometheusAlerts, /alert: AquilaBackendAppMetricsScrapeDown\s*\n\s*expr: min\(up\{job="backend_app_metrics"\}\) < 1[\s\S]*severity: critical[\s\S]*service: aquila-backend-app-metrics[\s\S]*title_ko: "백엔드 앱 메트릭 수집 실패"[\s\S]*impact_ko: "운행표 snapshot 잔여시간 게이지가 사라져 만료 24\/6시간 전 경보가 조용히 멈춥니다\."[\s\S]*action_ko: "backend 컨테이너 상태와 \/actuator\/prometheus 응답, docker network 내부 backend:8080 접근을 확인하세요\."/);
  assert.match(alertmanagerConfig, /receiver: operations-null/);
  assert.match(alertmanagerConfig, /templates:\s*\n\s*-\s*\/etc\/alertmanager\/templates\/\*\.tmpl/);
  assert.match(alertmanagerTemplate, /define "easysubway\.email\.subject"/);
  assert.match(alertmanagerTemplate, /define "easysubway\.status_ko"/);
  assert.match(alertmanagerTemplate, /define "easysubway\.severity_ko"/);
  assert.match(alertmanagerTemplate, /장애 발생/);
  assert.match(alertmanagerTemplate, /복구/);
  assert.match(alertmanagerTemplate, /주의/);
  assert.match(alertmanagerTemplate, /긴급/);
  assert.match(alertmanagerTemplate, /title_ko/);
  assert.match(alertmanagerTemplate, /impact_ko/);
  assert.match(alertmanagerTemplate, /action_ko/);
  assert.match(alertmanagerTemplate, /Asia\/Seoul/);
  assert.doesNotMatch(alertmanagerTemplate, /\.GeneratorURL/);
  assert.doesNotMatch(alertmanagerTemplate, /alertmanager:9093|prometheus:9090|backend:8080|back-worker:8080/);

  assert.match(grafanaDatasource, /name: easysubway-prometheus/);
  assert.match(grafanaDatasource, /type: prometheus/);
  assert.match(grafanaDatasource, /url: http:\/\/prometheus:9090/);
  assert.match(grafanaDatasource, /isDefault: true/);
});

