test("build-release-callback.mjs는 스키마 유효 payload와 공유 fixture 벡터 HMAC을 낸다", async () => {
  const vec = JSON.parse(read("tools/datapack/fixtures/release-callback-signature-vector.json"));
  const f = vec.fields;
  const { execFileSync } = await import("node:child_process");
  const out = execFileSync("node", ["tools/datapack/build-release-callback.mjs"], {
    cwd: root, encoding: "utf8",
    env: { ...process.env,
      RELEASE_REQUEST_ID: f.releaseRequestId, RELEASE_SEQUENCE: String(f.releaseSequence),
      TARGET_CHANNEL: f.channel, WORKFLOW_RUN_URL: f.workflowRunUrl,
      MANIFEST_SHA256: f.manifestSha256, SQLITE_SHA256: f.sqliteSha256, GZIP_SHA256: f.gzipSha256,
      EVIDENCE_BUNDLE_SHA256: f.evidenceBundleSha256, VALIDATOR_STATUS: f.validatorStatus,
      ROUTE_REGRESSION_STATUS: f.routeRegressionStatus, PUBLISH_STATUS: f.publishStatus,
      EASYSUBWAY_DATAPACK_CALLBACK_HMAC_KEY: vec.hmacKey },
  });
  const payload = JSON.parse(out);
  assert.equal(payload.artifactKind, "datapack-release-callback");
  assert.equal(payload.schemaVersion, 2);
  assert.equal(payload.callbackVerifier.kind, "payload-signature");
  assert.equal(payload.callbackVerifier.value, vec.expectedHmacHex); // node↔Java 합의
  // required 15필드 + additionalProperties:false 준수
  assert.deepEqual(Object.keys(payload).sort(), ["artifactKind","callbackVerifier","channel","evidenceBundleSha256","gzipSha256","idempotencyKey","manifestSha256","publishStatus","releaseRequestId","releaseSequence","routeRegressionStatus","schemaVersion","sqliteSha256","validatorStatus","workflowRunUrl"]);
});

async function classifyChangedFiles(files) {
  const dir = await mkdtemp(path.join(tmpdir(), "easysubway-ci-"));
  const changedFilesPath = path.join(dir, "changed-files.txt");
  await writeFile(changedFilesPath, `${files.join("\n")}\n`);

  const scriptPath = path.join(root, "tools/ci/detect-changed-paths.sh");
  assert.ok(existsSync(scriptPath), "Expected tools/ci/detect-changed-paths.sh to exist");

  const { stdout } = await execFileAsync("bash", [scriptPath, changedFilesPath], {
    cwd: root,
    env: {
      ...process.env,
      GITHUB_OUTPUT: "",
      GITHUB_STEP_SUMMARY: "",
    },
  });
  return Object.fromEntries(stdout.trim().split("\n").map((line) => line.split("=")));
}

test("get-off-alarm policy contract pins the no-location, degrade-ladder invariants", () => {
  const policyPath = "apps/mobile/release/get-off-alarm-policy.json";
  assert.equal(existsSync(path.join(root, policyPath)), true, "get-off-alarm policy must exist");

  const policy = readJson(policyPath);
  assert.equal(policy.schemaVersion, 1);
  assert.equal(policy.applicationId, "easysubway");
  assert.equal(policy.androidApplicationId, "com.easysubway.app");
  assert.equal(policy.policyName, "get-off-alarm-policy");
  assert.equal(policy.issue, 1766);
  assert.equal(policy.parentTracker, 1762);

  // 위치 미사용 불변(area:privacy — 위치 추적으로 절대 회귀 금지).
  assert.equal(policy.locationTrackingUsed, false);

  // 리드타임 기본값은 Dart 스케줄러의 단일 진실 원본.
  assert.equal(policy.leadTime.defaultLeadSeconds, 120);
  assert.equal(policy.leadTime.transferAlarmDefaultOn, true);
  assert.ok(policy.leadTime.minLeadSeconds < policy.leadTime.defaultLeadSeconds);
  assert.ok(policy.leadTime.maxLeadSeconds > policy.leadTime.defaultLeadSeconds);

  // 단일 경로 활성 알림(동시 다중 경로는 v1 비범위).
  assert.equal(policy.activeAlarm.maxConcurrentRoutes, 1);
  assert.equal(policy.activeAlarm.cancelOnRouteEnd, true);
  assert.equal(policy.activeAlarm.cancelOnNewSearch, true);

  // 정확 알람 강등 사다리: SCHEDULE_EXACT_ALARM 요청, USE_EXACT_ALARM 금지,
  // 거부 시 고지 문구와 함께 부정확으로 강등 — 무음 실패 금지.
  assert.equal(policy.exactAlarm.permissionName, "SCHEDULE_EXACT_ALARM");
  assert.equal(policy.exactAlarm.forbiddenPermission, "USE_EXACT_ALARM");
  assert.equal(policy.exactAlarm.degradeToInexactOnDeny, true);
  assert.equal(policy.exactAlarm.silentFailureAllowed, false);
  assert.ok(policy.exactAlarm.inexactNoticeKo.length > 0);

  // 실시간 보정은 온라인 전용 overlay 재사용; 오프라인은 PLANNED 유지.
  assert.equal(policy.realtimeCorrection.recomputeOnForeground, true);
  assert.equal(policy.realtimeCorrection.offlineEtaSource, "PLANNED");
  assert.equal(policy.realtimeCorrection.correctionOverlayIssue, 1416);
});

test("하차 알림 Android source manifest는 예약·부팅 복원 receiver를 exported=false로 선언한다", () => {
  const androidManifest = read("apps/mobile/android/app/src/main/AndroidManifest.xml");

  assert.match(
    androidManifest,
    /<receiver\s+android:name="com\.dexterous\.flutterlocalnotifications\.ScheduledNotificationReceiver"\s+android:exported="false"\s*\/>/,
  );
  // #2154: 재부팅·package replace 뒤 예약 자동 복원용 공식 boot receiver를
  // exported=false로 등록하고 네 부팅 계열 action을 명시 선언한다.
  const bootReceiver = androidManifest.match(
    /<receiver\s+android:name="com\.dexterous\.flutterlocalnotifications\.ScheduledNotificationBootReceiver"\s+android:exported="false"\s*>([\s\S]*?)<\/receiver>/,
  );
  assert.ok(
    bootReceiver,
    "ScheduledNotificationBootReceiver must be declared with android:exported=\"false\".",
  );
  for (const action of [
    "android.intent.action.BOOT_COMPLETED",
    "android.intent.action.MY_PACKAGE_REPLACED",
    "android.intent.action.QUICKBOOT_POWERON",
    "com.htc.intent.action.QUICKBOOT_POWERON",
  ]) {
    assert.match(
      bootReceiver[1],
      new RegExp(`<action\\s+android:name="${action.replace(/\./g, "\\.")}"\\s*/>`),
      `boot receiver must include intent action ${action}`,
    );
  }
  // #2154: 부팅 복원 권한을 source manifest가 직접 선언한다(WorkManager도 병합).
  assert.match(
    androidManifest,
    /<uses-permission\s+android:name="android\.permission\.RECEIVE_BOOT_COMPLETED"\s*\/>/,
  );
});

