test("데이터팩 만료 감시 workflow는 SLA 임계보다 촘촘한 cron으로 expiry alert를 배선한다", () => {
  assert.ok(
    existsSync(path.join(root, ".github/workflows/datapack-expiry-alert.yml")),
    "datapack expiry alert workflow must exist",
  );

  const workflow = read(".github/workflows/datapack-expiry-alert.yml");
  const policy = readJson("apps/mobile/release/datapack-freshness-sla.json");

  assert.match(workflow, /^name: Data Pack Expiry Alert$/m);
  assert.match(workflow, /schedule:[\s\S]*cron: "23 \*\/4 \* \* \*"/);
  assert.match(workflow, /schedule:[\s\S]*cron: "41 0 \* \* \*"/);
  assert.match(workflow, /workflow_dispatch:/);
  assert.match(workflow, /permissions:\s*\n\s*contents: read/);
  assert.match(
    workflow,
    /concurrency:\s*\n\s*group: datapack-expiry-alert-\$\{\{ github\.workflow \}\}-\$\{\{ github\.ref \}\}-\$\{\{ github\.event\.schedule \|\| github\.event_name \}\}/,
  );

  // 기존 데이터팩 릴리스 workflow와 동일하게 action SHA를 고정한다.
  const releaseWorkflow = read(".github/workflows/datapack-release.yml");
  const checkoutSha = releaseWorkflow.match(/actions\/checkout@([0-9a-f]{40})/)?.[1];
  const setupNodeSha = releaseWorkflow.match(/actions\/setup-node@([0-9a-f]{40})/)?.[1];
  const uploadArtifactSha = releaseWorkflow.match(/actions\/upload-artifact@([0-9a-f]{40})/)?.[1];
  const slackActionSha = releaseWorkflow.match(/slackapi\/slack-github-action@([0-9a-f]{40})/)?.[1];
  assert.ok(checkoutSha, "release workflow must pin checkout SHA for comparison");
  assert.match(workflow, new RegExp(`actions/checkout@${checkoutSha}`));
  assert.match(workflow, new RegExp(`actions/setup-node@${setupNodeSha}`));
  assert.match(workflow, new RegExp(`actions/upload-artifact@${uploadArtifactSha}`));
  assert.match(workflow, new RegExp(`slackapi/slack-github-action@${slackActionSha}`));

  // secret 없으면 성공 종료하는 skip 패턴 (datapack-release.yml의 Slack skip 패턴 참고).
  assert.match(workflow, /EASYSUBWAY_ENV_SECRET:\s*\$\{\{\s*secrets\.EASYSUBWAY_ENV\s*\}\}/);
  assert.match(workflow, /::notice/);
  assert.match(workflow, /umask 077/);
  assert.doesNotMatch(workflow, /EASYSUBWAY_OBJECT_STORAGE_(ACCESS|SECRET)_KEY/);
  assert.doesNotMatch(workflow, /SIGNING_(PRIVATE|PUBLIC)_KEY/);

  // manifest 다운로드와 스크립트 호출부.
  assert.match(workflow, /curl -fsS --connect-timeout 10 --max-time 30 "\$\{[A-Z_]*BASE_URL[A-Z_]*\}\/catalog\/current\.json"/);
  assert.match(workflow, /node tools\/datapack\/check-datapack-expiry-alert\.mjs/);
  assert.match(workflow, /node tools\/datapack\/source-operation\.mjs check-approvals/);
  assert.match(workflow, /^  provider-approval-expiry:\s*$/m);
  assert.match(workflow, /^    name: Provider Approval Expiry$/m);
  assert.match(workflow, /provider-approval-expiry:[\s\S]*id:\s*check[\s\S]*GITHUB_OUTPUT/);
  assert.match(workflow, /provider-approval-expiry:[\s\S]*github\.event\.schedule == '41 0 \* \* \*'/);
  assert.match(workflow, /datapack-expiry-alert:[\s\S]*github\.event\.schedule == '23 \*\/4 \* \* \*'/);
  assert.doesNotMatch(workflow, /notification_due/);
  assert.match(workflow, /provider-approval-expiry:[\s\S]*steps\.check\.outputs\.status == 'WARNING'[\s\S]*slackapi\/slack-github-action@/);
  assert.match(workflow, /--manifest\s+"/);
  assert.match(workflow, /--output\s+"/);

  // --policy를 명시하면 freshness SLA 경로와 일치해야 하고, 미명시라면 스크립트 기본값과 일치해야 한다.
  const policyFlagMatch = workflow.match(/--policy\s+"?([^"\s]+)"?/);
  if (policyFlagMatch) {
    assert.equal(policyFlagMatch[1], "apps/mobile/release/datapack-freshness-sla.json");
  }
  assert.equal(policy.monitoring.alertBeforePackExpiry, "PT6H");

  // evidence artifact 업로드.
  assert.match(workflow, /uses: actions\/upload-artifact@/);
  assert.match(workflow, /if-no-files-found: error/);

  // alert.status / alert.severity 파싱과 게이팅.
  assert.match(workflow, /alert\.status/);
  assert.match(workflow, /alert\.severity/);
  assert.match(workflow, /FIRING/);
  assert.match(workflow, /critical/);

  // Slack 알림 게이트: 웹훅 미설정 시 skip.
  assert.match(workflow, /SLACK_RELEASE_WEBHOOK_URL/);
  assert.match(workflow, /secrets\.SLACK_RELEASE_WEBHOOK_URL/);

  for (const file of workflowFiles()) {
    const source = read(file);
    assertActionsEnvSecretPolicy(file, source);
  }
});

test("KRIC source 후보 evidence workflow는 고정 allowlist와 sanitized artifact 경계를 유지한다", () => {
  const workflowPath = ".github/workflows/kric-source-candidate-evidence.yml";
  assert.ok(existsSync(path.join(root, workflowPath)), "KRIC evidence workflow must exist");

  const workflow = read(workflowPath);
  const triggerBlock = workflow.match(/^on:\s*\n([\s\S]*?)^jobs:/m)?.[1] ?? "";
  const triggers = [...triggerBlock.matchAll(/^ {2}([a-z_]+): *$/gm)].map((match) => match[1]);
  const inputBlock = triggerBlock.match(/workflow_dispatch:\s*\n\s+inputs:\s*\n([\s\S]*)/)?.[1] ?? "";
  const inputNames = [...inputBlock.matchAll(/^ {6}([A-Za-z][A-Za-z0-9_-]*): *$/gm)]
    .map((match) => match[1]);
  const candidateBlock = inputBlock.match(/^ {6}candidate: *\n([\s\S]*)/m)?.[1] ?? "";
  const optionsBlock = candidateBlock.match(/^ {8}options: *\n((?:^ {10}- [^\n]+\n?)+)/m)?.[1] ?? "";
  const candidateOptions = [...optionsBlock.matchAll(/^ {10}- ([a-z0-9-]+) *$/gm)]
    .map((match) => match[1]);

  assert.deepEqual(triggers, ["workflow_dispatch"]);
  assert.deepEqual(inputNames, ["candidate"]);
  assert.match(candidateBlock, /^ {8}type: choice$/m);
  assert.deepEqual(candidateOptions, [
    "kric-transfer-movement-standard",
  ]);
  assert.ok(!candidateOptions.includes("kric-subway-route-info"));
  assert.ok(!candidateOptions.includes("kric-station-info"));
  assert.ok(!candidateOptions.includes("kric-transfer-movement-detailed"));
  const sourceCandidates = readJson("tools/datapack/source-candidates.json").candidates;
  for (const candidateId of candidateOptions) {
    const candidate = sourceCandidates.find((entry) => entry.id === candidateId);
    assert.equal(candidate?.sampleEvidenceStatus, "sample_url_documented_key_required");
  }
  const permissions = workflow.match(/^ {4}permissions: *\n((?:^ {6}[^\n]+\n?)+)/m)?.[1]
    .trim()
    .split("\n")
    .map((line) => line.trim());
  assert.deepEqual(permissions, ["contents: read"]);

  const secretNames = [...workflow.matchAll(/secrets\.([A-Z0-9_]+)/g)].map((match) => match[1]);
  assert.deepEqual([...new Set(secretNames)], ["KRIC_SERVICE_KEY"]);
  assert.match(
    workflow,
    /if: \$\{\{ github\.ref == format\('refs\/heads\/\{0\}', github\.event\.repository\.default_branch\) \}\}/,
  );
  assert.match(workflow, /ref: \$\{\{ github\.sha \}\}/);
  assert.doesNotMatch(workflow, /ref: \$\{\{ github\.event\.repository\.default_branch \}\}/);
  assert.equal((workflow.match(/\$\{\{ inputs\.candidate \}\}/g) ?? []).length, 1);
  assert.match(workflow, /KRIC_CANDIDATE_ID: \$\{\{ inputs\.candidate \}\}/);
  assert.match(workflow, /collect-kric-source-candidate-evidence\.mjs/);
  const collector = read("tools/datapack/collect-kric-source-candidate-evidence.mjs");
  assert.match(collector, /build-source-candidate-sample-evidence\.mjs/);
  assert.match(collector, /validate-source-candidate-sample\.mjs/);
  assert.match(workflow, /retention-days: 14/);
  assert.match(workflow, /include-hidden-files: false/);
  assert.match(workflow, /if-no-files-found: error/);

  const referenceWorkflow = read(".github/workflows/tago-schedule-collection.yml");
  for (const action of ["actions/checkout", "actions/setup-node", "actions/upload-artifact"]) {
    const pinnedSha = referenceWorkflow.match(new RegExp(`${action}@([0-9a-f]{40})`))?.[1];
    assert.ok(pinnedSha, `${action} reference pin must exist`);
    assert.match(workflow, new RegExp(`${action}@${pinnedSha}`));
  }

  const uploadBlock = workflow.match(/uses: actions\/upload-artifact@[0-9a-f]{40}[\s\S]*$/)?.[0] ?? "";
  assert.match(uploadBlock, /sample\.json/);
  assert.match(uploadBlock, /report\.txt/);
  assert.match(uploadBlock, /hashes\.json/);
  assert.doesNotMatch(uploadBlock, /\braw\b|response|\.env|dotenv/i);
  assert.doesNotMatch(workflow, /github\.event\.inputs\.(?:url|host|ref|command|output|path)/i);
});

test("#1702 보행 프로필 프리셋 정책 JSON은 프리셋 계수·시설 제약·유형 매핑을 고정한다", () => {
  const policyPath = "apps/mobile/release/mobility-profile-policy.json";
  assert.equal(existsSync(path.join(root, policyPath)), true, "mobility-profile-policy JSON must exist");

  const policy = readJson(policyPath);
  assert.equal(policy.schemaVersion, 1);
  assert.equal(policy.artifactKind, "mobility-profile-policy");
  assert.equal(policy.anchorWalkSpeedMps, 1.2);

  // 프리셋 4종 계수·시설 제약. speedFactor 1.0 = 표준 속도(회귀 불변).
  assert.equal(policy.presets.STANDARD.speedFactor, 1.0);
  assert.equal(policy.presets.STANDARD.facilityConstraint, "NONE");
  assert.equal(policy.presets.SLOW.speedFactor, 1.35);
  assert.equal(policy.presets.SLOW.facilityConstraint, "NONE");
  assert.equal(policy.presets.NO_STAIRS.speedFactor, 1.2);
  assert.equal(policy.presets.NO_STAIRS.facilityConstraint, "NO_STAIRS");
  assert.equal(policy.presets.STEP_FREE.speedFactor, 1.0);
  assert.equal(policy.presets.STEP_FREE.facilityConstraint, "ELEVATOR_ONLY");
  assert.equal(policy.presets.STEP_FREE.elevatorWaitSeconds, 60);

  // 이동 유형 → 기본 프리셋 매핑 6종.
  assert.deepEqual(policy.mobilityTypeMapping, {
    SENIOR: "SLOW",
    PREGNANT: "SLOW",
    TEMPORARY_INJURY: "SLOW",
    LUGGAGE: "NO_STAIRS",
    STROLLER: "STEP_FREE",
    WHEELCHAIR: "STEP_FREE",
  });
});

test("#1702 backend ProfileWalkTimeCalculator enum은 정책 JSON 계수·매핑과 동기화된다", () => {
  const policy = readJson("apps/mobile/release/mobility-profile-policy.json");
  const source = read("backend/src/main/java/com/easysubway/route/domain/ProfileWalkTimeCalculator.java");

  // backend는 정수 speedFactorPercent, JSON은 소수 speedFactor. Math.round(factor*100)로 상호 고정.
  const percentByPreset = {};
  for (const match of source.matchAll(/\b(STANDARD|SLOW|NO_STAIRS|STEP_FREE)\((\d+)\)/g)) {
    percentByPreset[match[1]] = Number(match[2]);
  }
  assert.deepEqual(percentByPreset, {
    STANDARD: 100,
    SLOW: 135,
    NO_STAIRS: 120,
    STEP_FREE: 100,
  });
  for (const preset of ["STANDARD", "SLOW", "NO_STAIRS", "STEP_FREE"]) {
    assert.equal(
      Math.round(policy.presets[preset].speedFactor * 100),
      percentByPreset[preset],
      `${preset} JSON speedFactor must match backend speedFactorPercent`,
    );
  }

  // STEP_FREE 승강기 대기 초는 backend 상수와 JSON이 일치한다.
  assert.match(source, /STEP_FREE_FACILITY_WAIT_SECONDS\s*=\s*60\b/);
  assert.equal(policy.presets.STEP_FREE.elevatorWaitSeconds, 60);

  // presetFor switch 매핑이 JSON mobilityTypeMapping과 일치한다. case 라벨 나열 순서는 의미에 영향을 주지 않으므로
  // 라벨 집합을 정렬해 비교한다(선언 순서가 바뀌어도 계약이 깨지지 않도록).
  const assertCaseLabels = (presetName, expectedLabels) => {
    const match = source.match(
      new RegExp(`case\\s+([A-Z_,\\s]+?)\\s*->\\s*MobilityPreset\\.${presetName}\\s*;`),
    );
    assert.ok(match, `presetFor switch must have a case clause mapping to MobilityPreset.${presetName}`);
    const actualLabels = match[1].split(",").map((label) => label.trim()).sort();
    assert.deepEqual(actualLabels, [...expectedLabels].sort());
  };
  assertCaseLabels("SLOW", ["SENIOR", "PREGNANT", "TEMPORARY_INJURY"]);
  assertCaseLabels("NO_STAIRS", ["LUGGAGE"]);
  assertCaseLabels("STEP_FREE", ["STROLLER", "WHEELCHAIR"]);
  assert.equal(policy.mobilityTypeMapping.SENIOR, "SLOW");
  assert.equal(policy.mobilityTypeMapping.PREGNANT, "SLOW");
  assert.equal(policy.mobilityTypeMapping.TEMPORARY_INJURY, "SLOW");
  assert.equal(policy.mobilityTypeMapping.LUGGAGE, "NO_STAIRS");
  assert.equal(policy.mobilityTypeMapping.STROLLER, "STEP_FREE");
  assert.equal(policy.mobilityTypeMapping.WHEELCHAIR, "STEP_FREE");
});

test("#1702 mobile 파생 상수 Dart는 정책 JSON 계수·매핑과 동기화된다", () => {
  const policy = readJson("apps/mobile/release/mobility-profile-policy.json");
  const dartPath = "apps/mobile/lib/features/mobility_profile/mobility_profile_policy.dart";
  assert.equal(existsSync(path.join(root, dartPath)), true, "mobility_profile_policy.dart must exist");
  const dart = read(dartPath);

  // anchor 속도·승강기 대기 초.
  assert.match(dart, /anchorWalkSpeedMps\s*=\s*1\.2\b/);
  assert.equal(policy.anchorWalkSpeedMps, 1.2);
  assert.match(dart, /stepFreeElevatorWaitSeconds\s*=\s*60\b/);
  assert.equal(policy.presets.STEP_FREE.elevatorWaitSeconds, 60);

  // 프리셋 4종 speedFactor·시설 제약이 Dart const map과 JSON에서 일치한다.
  const specByPreset = {
    standard: { key: "STANDARD", constraint: "FacilityConstraint.none" },
    slow: { key: "SLOW", constraint: "FacilityConstraint.none" },
    noStairs: { key: "NO_STAIRS", constraint: "FacilityConstraint.noStairs" },
    stepFree: { key: "STEP_FREE", constraint: "FacilityConstraint.elevatorOnly" },
  };
  for (const [enumName, spec] of Object.entries(specByPreset)) {
    const factor = policy.presets[spec.key].speedFactor;
    const factorLiteral = Number.isInteger(factor) ? `${factor}\\.0` : `${factor}`;
    const block = dart.match(
      new RegExp(`MobilityPreset\\.${enumName}:\\s*MobilityPresetSpec\\(([\\s\\S]*?)\\)`),
    )?.[1];
    assert.ok(block, `Dart preset spec for ${enumName} must exist`);
    assert.match(block, new RegExp(`speedFactor:\\s*${factorLiteral}\\b`));
    assert.match(block, new RegExp(`facilityConstraint:\\s*${spec.constraint.replace(".", "\\.")}\\b`));
  }

  // 이동 유형 매핑 6종이 Dart const map과 JSON에서 일치한다.
  const dartTypeToEnum = {
    SENIOR: "senior",
    PREGNANT: "pregnant",
    TEMPORARY_INJURY: "temporaryInjury",
    LUGGAGE: "luggage",
    STROLLER: "stroller",
    WHEELCHAIR: "wheelchair",
  };
  const presetToEnum = {
    STANDARD: "standard",
    SLOW: "slow",
    NO_STAIRS: "noStairs",
    STEP_FREE: "stepFree",
  };
  for (const [jsonType, preset] of Object.entries(policy.mobilityTypeMapping)) {
    assert.match(
      dart,
      new RegExp(`MobilityType\\.${dartTypeToEnum[jsonType]}:\\s*MobilityPreset\\.${presetToEnum[preset]}\\b`),
    );
  }
});

test("#1702 STANDARD 환승 parity 리포트는 재현 가능하고 ±10% 이내 편차를 고정한다", async () => {
  const trackedPath = "tools/datapack/reports/mobility-standard-transfer-parity-report.json";
  assert.equal(existsSync(path.join(root, trackedPath)), true, "parity report must be tracked");

  const outputDir = await mkdtemp(path.join(tmpdir(), "mobility-parity-"));
  const output = path.join(outputDir, "mobility-standard-transfer-parity-report.json");
  await execFileAsync(process.execPath, [
    "tools/datapack/build-mobility-standard-transfer-parity-report.mjs",
    "--baseline",
    "tools/datapack/reports/baseline-ingestion-gate-report.json",
    "--policy",
    "apps/mobile/release/mobility-profile-policy.json",
    "--output",
    output,
  ], { cwd: root });

  // 재현성: 재생성 결과가 tracked 산출물과 바이트 단위로 동일해야 한다.
  assert.equal(readFileSync(output, "utf8"), read(trackedPath));

  const report = JSON.parse(readFileSync(output, "utf8"));
  assert.equal(report.schemaVersion, 1);
  assert.equal(report.artifactKind, "mobility-standard-transfer-parity-report");
  assert.equal(report.issue, 1702);
  assert.equal(report.standardPreset.speedFactorPercent, 100);
  assert.equal(report.toleranceProfile.maxDeviationPercent, 10);
  // STANDARD는 speedFactor 1.0이므로 baseline과 0% 편차, 모두 ±10% 이내.
  assert.equal(report.summary.maxAbsoluteDeviationPercent, 0);
  assert.equal(report.summary.allWithinTolerance, true);
  assert.ok(report.directionPairs.length >= 2);
  for (const pair of report.directionPairs) {
    assert.equal(pair.standardPresetSeconds, pair.baselineTransferSeconds);
    assert.equal(pair.deviationPercent, 0);
    assert.equal(pair.withinTolerance, true);
    assert.ok(Math.abs(pair.deviationPercent) <= report.toleranceProfile.maxDeviationPercent);
  }
});

test("서비스·위치정보 이용약관은 공개 경로와 사실 계약을 함께 유지한다", () => {
  const controller = read(
    "backend/src/main/java/com/easysubway/legal/adapter/in/web/PrivacyPolicyPageController.java",
  );
  const security = read("backend/src/main/java/com/easysubway/common/security/SecurityConfig.java");
  const terms = read("backend/src/main/resources/templates/legal/terms.html");
  const locationTerms = read("backend/src/main/resources/templates/legal/location-terms.html");

  for (const route of ["/terms", "/easysubway/terms", "/location-terms", "/easysubway/location-terms"]) {
    assert.ok(controller.includes(`\"${route}\"`), `legal controller must map ${route}`);
    assert.ok(security.includes(`\"${route}\"`), `public security must permit ${route}`);
  }

  assert.match(terms, /쉬운 지하철 서비스 이용약관/);
  assert.match(terms, /제 16 조 \(운영자 정보 및 문의\)/);
  assert.match(terms, /현장 안내를 우선/);
  assert.match(terms, /서비스의 이용 요금은 무료/);
  assert.match(terms, /support@aquilaxk\.site/);
  assert.match(locationTerms, /쉬운 지하철 위치정보 이용약관/);
  assert.match(locationTerms, /가까운 역/);
  assert.match(locationTerms, /위치기반서비스는 무료/);
  assert.match(locationTerms, /접수일부터 최대 1년/);
  assert.match(locationTerms, /매일 보관 상한이 지난/);
  assert.match(locationTerms, /백업 생성일부터 최대 30일/);
  assert.match(locationTerms, /운영 환경의 일일 자동 작업/);
  assert.match(locationTerms, /제공받는 자는 카카오/);
  assert.match(locationTerms, /카카오맵 앱에는 현재 위치의 시작 좌표와 목적지 좌표/);
  assert.match(locationTerms, /카카오맵 웹에는 목적지 좌표/);
  assert.match(locationTerms, /privacy@aquilaxk\.site/);
  assert.doesNotMatch(locationTerms, /법정대리인의 동의를 받습니다/);
  assert.match(locationTerms, /제 16 조 \(사업자 및 위치정보관리책임자\)/);
  assert.match(locationTerms, /약관을 단순히 게시하거나 이용자가 열람했다는 사실만으로 별도 동의를 받은 것으로 보지 않습니다/);
  assert.doesNotMatch(`${terms}\n${locationTerms}`, /TBD|TODO|준비 중/);
});
